#include <stdio.h>
#include <stdlib.h>

struct qstr {
    size_t length;
    size_t capacity;
    char *data;
};

int main(void) {
    struct qstr *s = malloc(sizeof(struct qstr));   // 1: the struct
    if (!s) {
        fprintf(stderr, "out of memory\n");
        return 1;
    }
    s->capacity = 8;
    s->data = malloc(s->capacity);                  // 2: the array of chars
    if (!s->data) {
        free(s);
        fprintf(stderr, "out of memory\n");
        return 1;
    }
    sprintf(s->data, "CISC220");                    // 3: the characters
    s->length = 7;                                  // 4: you must set length yourself

    printf("data = %s, length = %zu, capacity = %zu\n", s->data, s->length, s->capacity);
    printf("sizeof(struct qstr) = %zu\n", sizeof(struct qstr));

    free(s->data);                                  // array first...
    free(s);                                        // ...then the struct
    return 0;
}

