    memcpy(s->data, "AB\0CD", 6);   // 5 characters, then the final '\0'
    s->length = 5;

    printf("s->length        = %zu\n", s->length);
    printf("strlen(s->data)  = %zu\n", strlen(s->data));
    for (size_t i = 0; i < s->length; i++) {
        if (s->data[i] == '\0') {
            printf("[\\0]");
        } else {
            printf("[%c]", s->data[i]);
        }
    }
    printf("\n");

    free(s->data);
    free(s);
    return 0;
}

blocks.text:
### Why `data` must point at heap memory

The notebook says the `data` array must **always** be dynamically allocated (made with `malloc`/`calloc`), so that the `qstr`:

- always has a valid array, for as long as the `qstr` exists;
- has an array that other functions can **re**allocate to make it bigger (Day 19's `realloc` only works on heap blocks);
- has an array that can be released with `free`.

Its second example breaks the rule on purpose. `badstring` points `data` at a **local** array:

blocks.code:
#include <stdio.h>
#include <stdlib.h>

struct qstr {
    size_t length;
    size_t capacity;
    char *data;
};

struct qstr *badstring() {
    struct qstr *s = malloc(sizeof(struct qstr));

    // set capacity and allocate array
    s->capacity = 8;
    char buffer[s->capacity];      // ohoh, automatic storage duration
    s->data = &buffer[0];

    // write a string into the array and set length
    sprintf(s->data, "CISC220");
    s->length = 7;

    return s;
}

int main(void) {
    struct qstr *str = badstring();

    // ohoh, attempt to print non-existant string
    puts(str->data);

    // ohoh, attempt to free memory not allocated by malloc
    free(str->data);

    // ok, free memory allocated by malloc, but program flow probably won't make it this far...
    free(str);

    return 0;
}

#ifndef QSTR_H
#define QSTR_H

// qstr.h (Day 20 part: the functions written today)

#include <stddef.h>

struct qstr {
    size_t length;
    size_t capacity;
    char *data;
};

// Returns a pointer to a newly allocated empty qstr, or NULL.
struct qstr *qstr_new(void);

// Returns a newly allocated qstr holding a copy of the C string s
// (an empty qstr if s is NULL), or NULL if allocation fails.
struct qstr *qstr_fromcstr(const char *s);

// Returns a newly allocated qstr holding a copy of the qstr s
// (an empty qstr if s is NULL), or NULL if allocation fails.
struct qstr *qstr_copy(const struct qstr *s);

// Makes s the empty string. Returns s, or NULL if s is NULL.
struct qstr *qstr_clear(struct qstr *s);

// Checked access: pointer to s->data[index], or NULL if s is NULL
// or index is not in 0 <= index < s->length.
char *qstr_get(const struct qstr *s, size_t index);

// Checked change: sets s->data[index] to c. Returns a pointer to that
// character, or NULL (and changes nothing) if s is NULL or index is invalid.
char *qstr_set(const struct qstr *s, size_t index, char c);

// Frees the data array and the struct. Does nothing if s is NULL.
void qstr_destroy(struct qstr *s);

#endif

// Allocates a new qstr of length 0 whose array has the given capacity.
// Returns a pointer to it, or NULL if allocation fails.
struct qstr *qstr_alloc(size_t capacity) {
    struct qstr *q = malloc(sizeof(struct qstr));
    if (!q) {
        fprintf(stderr, "qstr allocation error\n");
        return NULL;
    }
    if (capacity == 0) {                  // 1
        capacity = 1;
    }
    char *buf = calloc(capacity, 1);      // 2
    if (!buf) {
        free(q);                          // 3
        fprintf(stderr, "qstr->data allocation error\n");
        return NULL;
    }
    q->length = 0;
    q->capacity = capacity;
    q->data = buf;
    return q;
}

struct qstr *qstr_new(void) {
    return qstr_alloc(QSTR_DEFAULT_CAPACITY);
}

struct qstr *qstr_fromcstr(const char *s) {
    if (!s) {
        return qstr_new();
    }
    size_t len = strlen(s);
    struct qstr *q = qstr_alloc(len + 1); // + 1 for the '\0'
    if (q) {
        q->length = len;
        strcpy(q->data, s);
    }
    return q;
}

void qstr_destroy(struct qstr *s) {
    if (!s) {             // 1
        return;
    }
    free(s->data);        // 2
    s->length = 0;        // 3
    s->capacity = 0;
    s->data = NULL;
    free(s);              // 4
}

#include <stdio.h>

#include "qstr.h"

void show(const char *name, const struct qstr *q) {
    printf("%s: length = %zu, capacity = %zu, data = \"%s\"\n",
           name, q->length, q->capacity, q->data);
}

int main(void) {
    struct qstr *a = qstr_new();
    struct qstr *b = qstr_fromcstr("CISC220");
    struct qstr *c = qstr_fromcstr("");
    if (!a || !b || !c) {
        qstr_destroy(a);          // safe even if one of them is NULL
        qstr_destroy(b);
        qstr_destroy(c);
        return 1;
    }
    show("a", a);
    show("b", b);
    show("c", c);

    qstr_destroy(a);
    qstr_destroy(b);
    qstr_destroy(c);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#include "qstr.h"

int main(void) {
    struct qstr *s = qstr_fromcstr("cat");
    struct qstr *t = malloc(sizeof(struct qstr));
    if (!s || !t) {
        qstr_destroy(s);
        free(t);
        return 1;
    }
    *t = *s;              // copies the three members: length, capacity, data
    t->data[0] = 'b';     // t->data and s->data hold the SAME address

    printf("s: %s\nt: %s\n", s->data, t->data);
    printf("same array? %s\n", s->data == t->data ? "yes" : "no");

    free(t);              // only the struct: the array belongs to s
    qstr_destroy(s);
    return 0;
}

struct qstr *qstr_copy(const struct qstr *s) {
    if (!s) {
        return qstr_new();
    }
    struct qstr *q = qstr_alloc(s->capacity);
    if (q) {
        memcpy(q->data, s->data, s->length + 1);  // the notebook calls qstr_assign (Day 21)
        q->length = s->length;
    }
    return q;
}

struct qstr *qstr_clear(struct qstr *s) {
    if (!s) {
        return NULL;
    }
    s->data[0] = '\0';
    s->length = 0;
    return s;
}

char *qstr_get(const struct qstr *s, size_t index) {
    if (!s || index >= s->length) {
        return NULL;
    }
    return s->data + index;
}

char *qstr_set(const struct qstr *s, size_t index, char c) {
    char *res = qstr_get(s, index);
    if (!res) {
        return NULL;
    }
    s->data[index] = c;
    return res;
}

#include <stdio.h>

#include "qstr.h"

int main(void) {
    struct qstr *s = qstr_fromcstr("hello");
    if (!s) {
        return 1;
    }
    char *p = qstr_get(s, 1);
    printf("index 1: %c\n", *p);

    if (qstr_get(s, 5) == NULL) {
        printf("index 5: no such character\n");
    }

    qstr_set(s, 0, 'j');
    if (qstr_set(s, 99, '!') == NULL) {
        printf("index 99: not changed\n");
    }
    *qstr_get(s, 4) = 'y';                 // a valid pointer can be written through
    printf("%s (length %zu)\n", s->data, s->length);

    qstr_clear(s);
    printf("after clear: \"%s\" (length %zu, capacity %zu)\n",
           s->data, s->length, s->capacity);
    if (qstr_get(s, 0) == NULL) {
        printf("index 0: no such character\n");
    }

    qstr_destroy(s);
    return 0;
}

