write.prompt:
Using the definition

```c
struct qstr {
    size_t length;
    size_t capacity;
    char *data;
};
```

write the function `struct qstr *qstr_copy(const struct qstr *s)` **without calling any other `qstr_` function** (only `malloc`, `calloc`, `free` and `<string.h>` functions). It must return a pointer to a new `qstr` that is an **independent** copy of `*s`: changing the copy's characters must never change `s`. The copy has the same length, capacity and characters as `s` (remember that a `qstr` may contain `'\0'` in the middle). If `s` is `NULL`, return a new empty `qstr` of capacity 8. Return `NULL` if memory runs out, without leaking. Then explain in one sentence why `struct qstr *t = malloc(sizeof(struct qstr)); *t = *s;` is **not** an independent copy.

write.solution:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct qstr {
    size_t length;
    size_t capacity;
    char *data;
};

// Returns a new, independent copy of *s (an empty qstr of capacity 8
// if s is NULL), or NULL if memory runs out.
struct qstr *qstr_copy(const struct qstr *s) {
    struct qstr *q = malloc(sizeof(struct qstr));
    if (!q) {
        return NULL;
    }
    size_t cap = s ? s->capacity : 8;
    q->data = calloc(cap, 1);
    if (!q->data) {
        free(q);
        return NULL;
    }
    q->capacity = cap;
    q->length = 0;
    if (s) {
        memcpy(q->data, s->data, s->length + 1);
        q->length = s->length;
    }
    return q;
}

// *t = *s copies the pointer data, not the characters: t->data and s->data
// would point at the same array, so changing one changes the other
// (and destroying both would free that array twice).
